def mul_consecutive_nums(my_list):
    result = []
    for i in range(len(my_list) - 1):
        result.append(my_list[i] * my_list[i + 1])
    return result

def second_frequent(my_list):
    counter = {}
    for item in my_list:
        if item not in counter:
            counter[item] = 1
        else:
            counter[item] += 1

    sorted_counter = sorted(counter.items(), key=lambda x: x[1], reverse=True)

    second_most_frequent = sorted_counter[1][0]
    return second_most_frequent

def count_Set_Bits(n):
    count = 0
    for i in range(1, n+1):
        binary = bin(i)
        count += binary.count('1')
    return count

import re
def remove_char(string):
    return re.sub(r'[^a-zA-Z0-9]', '', string)

def prime_num(n):
    if n < 2:
        return False
    for i in range(2, int(n ** 0.5) + 1):
        if n % i == 0:
            return False
    return True
